1	package credit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"strings"
12		"unicode/utf8"
13	)
14	
15	// recordVersion 是当前记录文件格式版本。
16	const recordVersion = 1
17	
18	// fileData 是记录文件的磁盘格式。
19	type fileData struct {
20		Version       int            `json:"version"`
21		Courses       []*Course      `json:"courses"`
22		Students      []*Student     `json:"students"`
23		Requirements  []*Requirement `json:"requirements"`
24		Enrollments   []*Enrollment  `json:"enrollments"`
25		Waivers       []*Waiver      `json:"waivers"`
26		NextResultSeq int            `json:"nextResultSeq"`
27	}
28	
29	// Load 从 path 读取记录。
30	//
31	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
32	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
33	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
34	// 空文件同样视为损坏，而不是空记录。
35	//
36	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
37	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
38	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
39	// 绝不依据已读到的前半条记录继续办理业务。
40	//
41	// 同一个 JSON 对象内的字段归属只能确定一次：出现两个完全同名的字段，或
42	// 两个字段名只有大小写差异却都会被读取功能识别为同一条记录字段（课程的
43	// credit 与 Credit、修读的 student 与 Student、最外层的 courses 与
44	// COURSES 等），无论两个值是否相同、顺序是否相邻，整份文件都判为损坏。
45	// 规则同时适用于最外层对象与其中的每条课程、学生、要求、修读、免修记录：
46	// 后一份即使是空数组也不能盖掉前一份。字段名以 JSON 解码后的文字比较并
47	// 按现有解码规则做大小写折叠（直接写出、Unicode 转义、大小写写法语义
48	// 等同），无法用转义加大小写的组合绕开；限制只针对同一对象，不同记录
49	// 各自携带同名字段是正常结构，字符串值里提到字段名不算重复。只出现一次
50	// 的大小写写法仍照常识别（如只有 Credit 的课程按该值读取）；不指向任何
51	// 记录字段的未知键不在此列，继续按未知字段拒绝。
52	//
53	// JSON 字符串的原始内容必须能还原为合法 Unicode 文字：字符串中直接写入的
54	// 字节不是合法 UTF-8，或 \uXXXX 转义中出现未配对的高位/低位代理项（高位
55	// 代理项后没有紧跟低位代理项、孤立的低位代理项、两个高位代理项相连等），
56	// 整份文件都判为内容损坏——标准库会把这些内容静默替换成 U+FFFD，替换后的
57	// 编号或依据绝不能当成正常内容继续查询、核对或登记，哪怕问题只在一条已拒绝
58	// 免修的依据里或本次核对不涉及的课程名称里。检查只读不写：不替用户修补转义、
59	// 不删字符、不改动任何申请状态。合法文字不受影响：中文、直接写入的补充平面
60	// 字符、完整的高低代理项转义对、转义表达的控制字符，以及用户确实写入的
61	// “�”（U+FFFD）都按原样使用。
62	//
63	// 有效免修的依据校验与首次正常申请一致：任何状态为有效（approved）的免修，
64	// 其依据必须含有实际文字；依据为空，或全部由空白字符（空格、制表符、换行、
65	// 回车、全角空格 U+3000、不换行空格 U+00A0 等，允许混用）组成时，整份记录
66	// 按内容损坏拒绝读取，即使该要求另有通过修读也不例外。已拒绝申请的依据允许
67	// 为空或只有空白。检查只读不写：不会补填依据、不会改动免修状态，也不会修剪
68	// 含实际文字的依据中原有空白。
69	//
70	// 已拒绝（rejected）免修必须保留含实际文字的拒绝原因：reason 字段没有出现、
71	// 显式写成 JSON null、空字符串，或只含空白字符（空格、制表符、换行、回车、
72	// 全角空格 U+3000、不换行空格 U+00A0 等，允许混用），都算没有原因，整份记录
73	// 按内容损坏拒绝读取。被拒绝的申请必须能说明当时为什么没有生效，缺了原因的
74	// 文件不能作为正常学分记录继续使用：只要文件中有一份这样的申请就整份拒绝，
75	// 哪怕它不属于本次查询的学生，或其目标要求已另有通过修读、有效免修、照常能
76	// 算出学分，也不能跳过这份历史。字段名大小写与 Unicode 转义沿用既有识别规则
77	// （reason、Reason、REASON 及解码后等同的转义写法都指向同一字段），字段在
78	// 免修对象中的位置不影响结果。含实际文字的原因按原文保留（包括前后与中间的
79	// 空白），不要求固定措辞，也不根据当前课程要求重新判断旧申请；因依据为空被
80	// 拒绝的申请仍允许保留空依据。检查只读不写：不补写推测的原因、不删除申请、
81	// 不把状态改成有效。有效免修原本可以没有 reason，已撤销免修沿用既有读取与
82	// 核对行为，二者都不增加原因限制。
83	//
84	// 课程开放状态字段显式写成 JSON null（"open":null，open、Open、OPEN 及解码
85	// 后等同的 Unicode 转义写法都指向同一字段，字段在课程对象中的位置不影响
86	// 结果）时，整份记录按内容损坏拒绝读取。标准库把 null 解进普通 bool 不报错，
87	// 字段保持零值 false，未定状态会被读成明确停开，进而误拒新增修读，并在后续
88	// 保存时把 null 固化成 false；因此只要课程编号、名称、学分合法而开放状态
89	// 显式为空，就拒绝整份文件——该课程尚未被要求引用、本次只查看另一名学生
90	// 也不跳过它继续办理。true（开放）与 false（停开）仍是合法状态，停开课程
91	// 照常可以建立要求、已有修读照常提交成绩；字段完全省略时沿用既有读取规则，
92	// 本次不改动。课程名称、免修依据中的普通文字“null”（字符串值）不是状态空值；
93	// 最外层 null、空数组或空列表继续按各自既有规则读取。检查只读不写：不补填
94	// 状态、不删除课程、不另存部分记录。
95	func Load(path string) (s *Store, existed bool, err error) {
96		f, err := os.Open(path)
97		if err != nil {
98			if errors.Is(err, os.ErrNotExist) {
99				return NewStore(), false, nil
100			}
101			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
102		}
103		defer f.Close()
104	
105		fi, err := f.Stat()
106		if err != nil {
107			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
108		}
109		if fi.Size() == 0 {
110			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
111		}
112	
113		raw, err := io.ReadAll(f)
114		if err != nil {
115			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
116		}
117	
118		// 先按原始字节检查 JSON 字符串能否还原为合法 Unicode 文字。标准库解码
119		// 会把非法 UTF-8 字节与未配对的高/低位代理项转义静默替换成 U+FFFD，
120		// 替换后的学生编号、课程名称或免修依据绝不能当成正常内容继续办理业务
121		// （两个本来不同的编号可能被替换成同一个），这样的文件整份判为内容
122		// 损坏，哪怕问题只在一条已拒绝免修的依据里或本次核对不涉及的课程名称
123		// 里。检查只读不写：不修补转义、不删字符、不改动申请状态。
124		if err := scanStringUnicode(raw); err != nil {
125			return nil, true, fmt.Errorf(
126				"记录文件 %s 内容损坏（包含无效的 Unicode 文字：%v），未做任何修改",
127				path, err)
128		}
129	
130		// 先在 token 流上检查同一 JSON 对象内的字段归属。标准库直接解进结构
131		// 体时会用后一个重复键静默覆盖前一个，而且结构体字段按大小写不敏感
132		// 匹配 json 标签：同一门课程写了 "credit":4 与 "Credit":9（4 会被
133		// 9 悄悄顶替，两个键颠倒又变成 4），最外层同时写 courses 与 COURSES
134		// （后一份即使是空数组也会盖掉前一份），修读里的 student 与 Student
135		// 都无法明确说明字段归属。这样的记录必须整份判为损坏，绝不能据此
136		// 核对或办理——即使冲突只在本次查询没有涉及的课程或免修历史里。
137		// 仅扫描第一份完整值，其后内容仍由下方的“完整记录之后不得有多余
138		// 内容”检查处理。
139		var dupErr *duplicateFieldError
140		if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
141			if dupErr.first == dupErr.second {
142				return nil, true, fmt.Errorf(
143					"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
144					path, dupErr.field)
145			}
146			return nil, true, fmt.Errorf(
147				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定），未做任何修改",
148				path, dupErr.first, dupErr.second, dupErr.field)
149		}
150	
151		// 显式的 "open":null 必须在结构体解码之前拦截。标准库把 JSON null 解进
152		// 非指针 bool 时既不报错也不改字段，零值 false 会被原样保留——于是“开放
153		// 状态未确定”的课程被读成“停开”：课程列表显示停开、新增修读被误拒，
154		// 之后任何一次需要保存的操作还会把未定状态写成明确的 false。因此只要
155		// 课程对象显式给出开放状态字段（open/Open/OPEN 及解码后等同的 Unicode
156		// 转义写法，位置不限）而值是 null，整份文件判为内容损坏，哪怕该课程
157		// 尚未被任何要求引用、本次只查看另一名学生也不跳过它继续办理。扫描只读
158		// 不写：不补填状态、不删除课程；字段省略时的既有读取规则（按零值处理）
159		// 不在此列，课程名称、免修依据中的普通文字“null”也不是状态空值。
160		var openNullErr *nullCourseOpenError
161		if err := scanNullCourseOpen(bytes.NewReader(raw)); errors.As(err, &openNullErr) {
162			return nil, true, fmt.Errorf(
163				"记录文件 %s 内容损坏（%v），未做任何修改", path, err)
164		}
165	
166		// 已拒绝免修必须保留含实际文字的拒绝原因，同样要在结构体解码之前拦截：
167		// 解码后的 Waiver.Reason 是普通 string，字段没有出现、"reason":null 与
168		// "reason":"" 都会变成零值空串，无法区分，而这三种（连同只含空白的字符
169		// 串）本次都要拒绝。被拒绝的申请必须能说明当时为什么没有生效；缺了原因，
170		// check 列出的申请就没有解释，随后登记其他记录还会把这份不完整历史继续
171		// 保存。只要文件中有一份这样的已拒绝申请就整份判为内容损坏——哪怕它不
172		// 属于本次查询的学生，或其目标要求已另有通过修读、有效免修、照常能算出
173		// 学分，也不能跳过这份历史继续办理。扫描只读不写：不补写推测的原因、不
174		// 删除申请、不把状态改成有效。有效免修原本可以没有 reason，已撤销免修
175		// 沿用既有读取与核对行为，两者都不受此限制。
176		var missingReasonErr *missingRejectReasonError
177		if err := scanRejectedWaiverReasons(bytes.NewReader(raw)); errors.As(err, &missingReasonErr) {
178			return nil, true, fmt.Errorf(
179				"记录文件 %s 内容损坏（%v），未做任何修改", path, err)
180		}
181	
182		var data fileData
183		dec := json.NewDecoder(bytes.NewReader(raw))
184		dec.DisallowUnknownFields()
185		if err := dec.Decode(&data); err != nil {
186			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
187		}
188		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
189		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
190		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
191		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
192		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
193		// 片段。这些一律视为文件损坏。
194		var extra json.RawMessage
195		switch err := dec.Decode(&extra); {
196		case errors.Is(err, io.EOF):
197			// 唯一一份完整记录之后只有空白，符合格式。
198		case err == nil:
199			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
200		default:
201			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
202		}
203	
204		s = NewStore()
205		if err := s.loadData(&data); err != nil {
206			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
207		}
208		return s, true, nil
209	}
210	
211	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
212	func (s *Store) loadData(d *fileData) error {
213		if d.Version != recordVersion {
214			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
215		}
216	
217		// 课程
218		for _, c := range d.Courses {
219			if c == nil {
220				return errors.New("存在空的课程记录")
221			}
222			if c.ID == "" {
223				return errors.New("存在没有编号的课程")
224			}
225			if c.Name == "" {
226				return fmt.Errorf("课程 %s 没有名称", c.ID)
227			}
228			if c.Credit <= 0 {
229				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
230			}
231			if _, dup := s.courseByID[c.ID]; dup {
232				return fmt.Errorf("课程编号 %s 重复", c.ID)
233			}
234			s.courses = append(s.courses, c)
235			s.courseByID[c.ID] = c
236		}
237	
238		// 学生
239		for _, st := range d.Students {
240			if st == nil || st.ID == "" {
241				return errors.New("存在没有编号的学生记录")
242			}
243			if _, dup := s.studentByID[st.ID]; dup {
244				return fmt.Errorf("学生编号 %s 重复", st.ID)
245			}
246			s.students = append(s.students, st)
247			s.studentByID[st.ID] = st
248		}
249	
250		// 要求
251		for _, r := range d.Requirements {
252			if r == nil {
253				return errors.New("存在空的课程要求记录")
254			}
255			if r.StudentID == "" || r.ID == "" {
256				return errors.New("存在缺少学生编号或要求编号的课程要求")
257			}
258			if _, ok := s.studentByID[r.StudentID]; !ok {
259				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
260			}
261			if _, ok := s.courseByID[r.CourseID]; !ok {
262				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
263					r.StudentID, r.ID, r.CourseID)
264			}
265			key := reqKey(r.StudentID, r.ID)
266			if _, dup := s.reqByKey[key]; dup {
267				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
268			}
269			dk := dupKey(r.StudentID, r.CourseID)
270			if other, dup := s.reqByDup[dk]; dup {
271				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
272					r.StudentID, r.CourseID, other, r.ID)
273			}
274			s.requirements = append(s.requirements, r)
275			s.reqByKey[key] = r
276			s.reqByDup[dk] = r.ID
277		}
278	
279		// 修读
280		usedSeq := map[int]bool{}
281		for _, e := range d.Enrollments {
282			if e == nil {
283				return errors.New("存在空的修读记录")
284			}
285			if e.StudentID == "" || e.ID == "" {
286				return errors.New("存在缺少学生编号或修读编号的修读记录")
287			}
288			if _, ok := s.studentByID[e.StudentID]; !ok {
289				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
290			}
291			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
292			if r == nil {
293				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
294					e.StudentID, e.ID, e.ReqID)
295			}
296			if e.Term == "" {
297				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
298			}
299			switch e.Result {
300			case Enrolled, Passed, Failed:
301			default:
302				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
303			}
304			if e.Result == Enrolled {
305				if e.ResultSeq != 0 {
306					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
307				}
308			} else {
309				if e.ResultSeq <= 0 {
310					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
311				}
312				if usedSeq[e.ResultSeq] {
313					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
314				}
315				usedSeq[e.ResultSeq] = true
316			}
317			key := reqKey(e.StudentID, e.ID)
318			if _, dup := s.enrByKey[key]; dup {
319				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
320			}
321			s.enrollments = append(s.enrollments, e)
322			s.enrByKey[key] = e
323		}
324	
325		// 免修（被拒绝的申请允许指向当时不存在的要求、依据也可以为空；
326		// 已撤销的申请则必须保留一份曾经有效的申请所必需的信息）
327		approvedReq := map[ownerKey]string{} // (student, req) -> waiverID
328		for _, w := range d.Waivers {
329			if w == nil {
330				return errors.New("存在空的免修记录")
331			}
332			if w.StudentID == "" || w.ID == "" {
333				return errors.New("存在缺少学生编号或免修编号的免修记录")
334			}
335			if _, ok := s.studentByID[w.StudentID]; !ok {
336				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
337			}
338			switch w.Status {
339			case WaiverApproved, WaiverRejected, WaiverRevoked:
340			default:
341				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
342			}
343			switch w.Status {
344			case WaiverApproved:
345				// 有效免修的依据校验与首次正常申请完全一致：依据必须含有实际
346				// 文字，空串或全部由空白字符（空格、制表符、换行、全角空格
347				// U+3000、不换行空格 U+00A0 等，含混用）组成都按内容损坏
348				// 拒绝整份记录——这样的“有效免修”无法有据可查，即使该要求
349				// 另有通过修读也不能放过。检查只读不写，绝不修剪或改写文件
350				// 中已保存的依据原文，也不把它降级成已拒绝/已撤销。
351				if blankBasis(w.Basis) {
352					return fmt.Errorf("学生 %s 的有效免修 %s 缺少依据（依据为空或全部为空白字符）",
353						w.StudentID, w.ID)
354				}
355				rk := reqKey(w.StudentID, w.ReqID)
356				if s.reqByKey[rk] == nil {
357					return fmt.Errorf("有效免修 %s 指向的要求 %s 不存在或不属于该学生", w.ID, w.ReqID)
358				}
359				if other, dup := approvedReq[rk]; dup {
360					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
361						w.StudentID, w.ReqID, other, w.ID)
362				}
363				approvedReq[rk] = w.ID
364			case WaiverRevoked:
365				// 撤销只取消免修对课程要求的满足作用，不能把缺少原依据、
366				// 失去要求归属的记录变成合法历史：目标要求必须真实存在于
367				// 该免修所属学生名下（同号要求只在其他学生名下不算），
368				// 原依据必须含有非空白内容（空白口径与有效免修一致，全角
369				// 空格、不换行空格等同样不算实际依据）。检查只读不写，
370				// 依据中有实际文字时原有空白一律保留，绝不为了通过检查
371				// 改写保存下来的材料内容。失效历史不参与有效免修的唯一
372				// 性限制。
373				if s.reqByKey[reqKey(w.StudentID, w.ReqID)] == nil {
374					return fmt.Errorf("学生 %s 的已撤销免修 %s 目标要求无效（要求 %s 不存在于该学生名下）",
375						w.StudentID, w.ID, w.ReqID)
376				}
377				if blankBasis(w.Basis) {
378					return fmt.Errorf("学生 %s 的已撤销免修 %s 原依据为空", w.StudentID, w.ID)
379				}
380			case WaiverRejected:
381				// 已拒绝申请必须保留含实际文字的拒绝原因（字段缺失、null、空串
382				// 或全部为空白字符都算没有原因）。正常读取时这一点已由
383				// scanRejectedWaiverReasons 在结构体解码之前保证（缺失与 null 经
384				// 解码都会变成空串，无法再区分，所以必须在扫描阶段拦截）；这里
385				// 再兜底一次，使“拒绝历史必有原因”成为 loadData 自身的不变量，
386				// 直接构造 fileData 调用本函数也绕不过去。检查只读不写：不补写
387				// 推测的原因、不删除申请、不把状态改成有效。
388				if strings.TrimSpace(w.Reason) == "" {
389					return fmt.Errorf("学生 %s 的已拒绝免修 %s 缺少拒绝原因（原因为空或全部为空白字符）",
390						w.StudentID, w.ID)
391				}
392			}
393			key := reqKey(w.StudentID, w.ID)
394			if _, dup := s.waiverByKey[key]; dup {
395				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
396			}
397			s.waivers = append(s.waivers, w)
398			s.waiverByKey[key] = w
399		}
400	
401		if d.NextResultSeq < 0 {
402			return errors.New("结果提交序号计数器为负数")
403		}
404		for seq := range usedSeq {
405			if seq > d.NextResultSeq {
406				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
407			}
408		}
409		s.nextResultSeq = d.NextResultSeq
410		return nil
411	}
412	
413	// invalidTextError 表示待保存记录中含有无法原样写入文件的文字：某个字符串
414	// 字段不是合法 UTF-8。category 指出记录类别（课程、学生、课程要求、修读、
415	// 免修），id 是该条记录的编号（仅用于定位，编号本身也可能就是问题所在，
416	// 按原始字节呈现），field 指出具体字段。
417	type invalidTextError struct {
418		category string
419		id       string
420		field    string
421	}
422	
423	func (e *invalidTextError) Error() string {
424		return fmt.Sprintf(
425			"%s记录（编号 %s）的字段“%s”含无法原样保存的非法 UTF-8 文字",
426			e.category, e.id, e.field)
427	}
428	
429	// validateSaveText 检查全部待写入记录的字符串字段是否都是合法 UTF-8。
430	//
431	// 背景：encoding/json 在序列化时会把字符串里的非法 UTF-8 字节静默替换成
432	// U+FFFD（“�”）却照常返回成功。若直接保存，免修依据会被改写，两个本来
433	// 不同的学生编号还可能被替换成同一个编号，让原本可读的记录文件变成编号
434	// 重复的损坏文件，而命令却提示成功。因此凡是要写入文件的文字——课程、
435	// 学生、课程要求、修读、免修的编号、名称、学期、依据、原因等——都必须先
436	// 通过本检查，任何一个字段不合法就拒绝整次保存。
437	//
438	// 检查只读不补：绝不替换、清空或修补任何原始字符串，也不删除出问题的
439	// 那条历史（即使它只是一条已拒绝或已撤销的免修），更不会跳过该字段只存
440	// 其他记录。合法文字不受影响：中文、补充平面字符、用户确实输入的“�”
441	// （U+FFFD）都是合法 UTF-8；编号中合法的控制字符与免修依据中原有的空白
442	// 也原样保留。命令行里字面出现的“\uD800”只是反斜线加普通字母数字，是
443	// 合法 ASCII 文字，不按记录文件中的 Unicode 转义处理。
444	func (s *Store) validateSaveText() error {
445		for _, c := range s.courses {
446			if c == nil {
447				continue
448			}
449			if err := checkSaveText("课程", c.ID, "编号", c.ID); err != nil {
450				return err
451			}
452			if err := checkSaveText("课程", c.ID, "名称", c.Name); err != nil {
453				return err
454			}
455		}
456		for _, st := range s.students {
457			if st == nil {
458				continue
459			}
460			if err := checkSaveText("学生", st.ID, "编号", st.ID); err != nil {
461				return err
462			}
463		}
464		for _, r := range s.requirements {
465			if r == nil {
466				continue
467			}
468			if err := checkSaveText("课程要求", r.ID, "编号", r.ID); err != nil {
469				return err
470			}
471			if err := checkSaveText("课程要求", r.ID, "学生编号", r.StudentID); err != nil {
472				return err
473			}
474			if err := checkSaveText("课程要求", r.ID, "课程编号", r.CourseID); err != nil {
475				return err
476			}
477		}
478		for _, e := range s.enrollments {
479			if e == nil {
480				continue
481			}
482			if err := checkSaveText("修读", e.ID, "编号", e.ID); err != nil {
483				return err
484			}
485			if err := checkSaveText("修读", e.ID, "学生编号", e.StudentID); err != nil {
486				return err
487			}
488			if err := checkSaveText("修读", e.ID, "要求编号", e.ReqID); err != nil {
489				return err
490			}
491			if err := checkSaveText("修读", e.ID, "学期", e.Term); err != nil {
492				return err
493			}
494			if err := checkSaveText("修读", e.ID, "结果", string(e.Result)); err != nil {
495				return err
496			}
497		}
498		for _, w := range s.waivers {
499			if w == nil {
500				continue
501			}
502			if err := checkSaveText("免修", w.ID, "编号", w.ID); err != nil {
503				return err
504			}
505			if err := checkSaveText("免修", w.ID, "学生编号", w.StudentID); err != nil {
506				return err
507			}
508			if err := checkSaveText("免修", w.ID, "要求编号", w.ReqID); err != nil {
509				return err
510			}
511			if err := checkSaveText("免修", w.ID, "依据", w.Basis); err != nil {
512				return err
513			}
514			if err := checkSaveText("免修", w.ID, "状态", string(w.Status)); err != nil {
515				return err
516			}
517			if err := checkSaveText("免修", w.ID, "原因", w.Reason); err != nil {
518				return err
519			}
520		}
521		return nil
522	}
523	
524	// duplicateResultSeqError 表示待保存记录中有两份不同修读的已提交成绩共用同一个
525	// 正整数结果提交顺序编号。seq 是冲突的编号；first/second 各用完整学生编号与
526	// 修读编号共同指明冲突双方，便于调用方分辨不同学生名下编号相同的修读（例如
527	// 两名学生各有一份 e1）。顺序按修读在记录中的先后确定，first 先出现。
528	type duplicateResultSeqError struct {
529		seq           int
530		firstStudent  string
531		firstEnr      string
532		secondStudent string
533		secondEnr     string
534	}
535	
536	func (e *duplicateResultSeqError) Error() string {
537		return fmt.Sprintf(
538			"成绩提交顺序编号 %d 被两份不同修读的已提交成绩共用：学生 %s 的修读 %s 与学生 %s 的修读 %s",
539			e.seq, e.firstStudent, e.firstEnr, e.secondStudent, e.secondEnr)
540	}
541	
542	// validateResultSeqUniqueness 检查全部已提交成绩的结果提交顺序编号互不相同。
543	//
544	// 顺序编号刻画的是整份记录中每次“首次提交成绩”的先后，通过与未通过都占用
545	// 一次编号，它不按学生、课程要求或学期各自编号：同一学生的重复修读、不同
546	// 要求下的独立提交、不同学生的独立修读，只要两份不同修读的已提交成绩共用
547	// 同一个正整数编号，写出的文件随后就会被 Load 判为内容损坏。因此这样的
548	// 待保存记录必须在序列化与临时文件之前整次拒绝保存——绝不删修读、不替
549	// 调用方重新编号、不清成绩或免修历史，也不能用这份记录替换掉原本可用的
550	// 记录文件。
551	//
552	// 尚未提交结果、仍处于选课状态的修读沿用编号 0，多份并存不构成重复，本
553	// 检查直接跳过它们；判定只看已提交成绩携带的正整数编号，因此已提交编号有
554	// 空缺（不连续）合法，冲突记录之间夹着其他正常成绩或免修也不能掩盖冲突。
555	// 以修读在记录中的先后取最先相撞的一对，结果确定且与 map 遍历顺序无关。
556	func (s *Store) validateResultSeqUniqueness() error {
557		first := map[int]*Enrollment{}
558		for _, e := range s.enrollments {
559			if e == nil || e.Result == Enrolled {
560				// 选课记录的编号一律是 0，多份并存正常，不参与重复判定。
561				continue
562			}
563			if e.ResultSeq <= 0 {
564				// 本规则只管“正整数顺序编号被共用”：非正编号不是这里的判定对象。
565				continue
566			}
567			if prev := first[e.ResultSeq]; prev != nil {
568				return &duplicateResultSeqError{
569					seq:           e.ResultSeq,
570					firstStudent:  prev.StudentID,
571					firstEnr:     prev.ID,
572					secondStudent: e.StudentID,
573					secondEnr:     e.ID,
574				}
575			}
576			first[e.ResultSeq] = e
577		}
578		return nil
579	}
580	
581	// checkSaveText 校验单个待保存字段的文字是否为合法 UTF-8。
582	func checkSaveText(category, id, field, value string) error {
583		if !utf8.ValidString(value) {
584			return &invalidTextError{category: category, id: id, field: field}
585		}
586		return nil
587	}
588	
589	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
590	// 避免写到一半时损坏原文件。
591	//
592	// 写入前先做两项检查：
593	//
594	// 一是全部待保存字符串都必须是合法 UTF-8：标准库序列化会把非法字节静默
595	// 替换成 U+FFFD，因此含非法文字的数据绝不能进入序列化与临时文件阶段。
596	// 校验失败时整次保存直接返回错误——不创建/不改动目标文件（目标原本不
597	// 存在时也不会留下新记录文件或临时文件），不替换、清空或修补待保存记录
598	// 中的任何原始字符串，即使问题只出现在一条已拒绝或已撤销免修的字段里。
599	//
600	// 二是全部已提交成绩的结果提交顺序编号互不相同：顺序编号表示整份记录中
601	// 每次首次提交成绩的先后，通过与未通过都占用一次编号，不按学生、要求或
602	// 学期各自编号。两份不同修读（同一学生的重复修读或不同学生的独立修读，
603	// 无论修读编号、要求编号、学期是否相同，也无论两条记录是否相邻）的已提交
604	// 成绩共用同一个正整数编号时，写出的文件随后必然被 Load 判为内容损坏，
605	// 因此直接拒绝整次保存：错误点名目标文件、重复编号及冲突双方（完整学生
606	// 编号 + 修读编号），已有文件全部内容原样保留，目标原本不存在时不创建
607	// 记录文件也不遗留临时文件；待保存的内存记录同样原样保留——不删修读、
608	// 不替调用方调整顺序、不清成绩或免修历史。仍是选课、尚未提交结果的修读
609	// 沿用编号 0，多份并存不构成重复；已提交编号有空缺（不连续）仍合法。
610	func (s *Store) Save(path string) (err error) {
611		if err := s.validateSaveText(); err != nil {
612			return fmt.Errorf("记录中存在无法原样保存的文字，拒绝写入 %s：%w", path, err)
613		}
614		if err := s.validateResultSeqUniqueness(); err != nil {
615			return fmt.Errorf("记录中的成绩提交顺序编号冲突，拒绝写入 %s，已有文件保持原样：%w", path, err)
616		}
617		data := fileData{
618			Version:       recordVersion,
619			Courses:       s.courses,
620			Students:      s.students,
621			Requirements:  s.requirements,
622			Enrollments:   s.enrollments,
623			Waivers:       s.waivers,
624			NextResultSeq: s.nextResultSeq,
625		}
626		buf, err := json.MarshalIndent(&data, "", "  ")
627		if err != nil {
628			return fmt.Errorf("无法序列化记录：%w", err)
629		}
630		buf = append(buf, '\n')
631	
632		dir := filepath.Dir(path)
633		if dir == "" {
634			dir = "."
635		}
636		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
637		if err != nil {
638			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
639		}
640		tmpName := tmp.Name()
641		defer func() {
642			if err != nil {
643				tmp.Close()
644				os.Remove(tmpName)
645			}
646		}()
647		if _, err = tmp.Write(buf); err != nil {
648			return fmt.Errorf("写入记录文件失败：%w", err)
649		}
650		if err = tmp.Sync(); err != nil {
651			return fmt.Errorf("写入记录文件失败：%w", err)
652		}
653		if err = tmp.Close(); err != nil {
654			return fmt.Errorf("写入记录文件失败：%w", err)
655		}
656		if err = os.Chmod(tmpName, 0o600); err != nil {
657			return fmt.Errorf("设置记录文件权限失败：%w", err)
658		}
659		if err = os.Rename(tmpName, path); err != nil {
660			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
661		}
662		return nil
663	}
664

file.content:
package credit

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"unicode/utf8"
)

// recordVersion 是当前记录文件格式版本。
const recordVersion = 1

// fileData 是记录文件的磁盘格式。
type fileData struct {
	Version       int            `json:"version"`
	Courses       []*Course      `json:"courses"`
	Students      []*Student     `json:"students"`
	Requirements  []*Requirement `json:"requirements"`
	Enrollments   []*Enrollment  `json:"enrollments"`
	Waivers       []*Waiver      `json:"waivers"`
	NextResultSeq int            `json:"nextResultSeq"`
}

// Load 从 path 读取记录。
//
// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
// 空文件同样视为损坏，而不是空记录。
//
// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
// 绝不依据已读到的前半条记录继续办理业务。
//
// 同一个 JSON 对象内的字段归属只能确定一次：出现两个完全同名的字段，或
// 两个字段名只有大小写差异却都会被读取功能识别为同一条记录字段（课程的
// credit 与 Credit、修读的 student 与 Student、最外层的 courses 与
// COURSES 等），无论两个值是否相同、顺序是否相邻，整份文件都判为损坏。
// 规则同时适用于最外层对象与其中的每条课程、学生、要求、修读、免修记录：
// 后一份即使是空数组也不能盖掉前一份。字段名以 JSON 解码后的文字比较并
// 按现有解码规则做大小写折叠（直接写出、Unicode 转义、大小写写法语义
// 等同），无法用转义加大小写的组合绕开；限制只针对同一对象，不同记录
// 各自携带同名字段是正常结构，字符串值里提到字段名不算重复。只出现一次
// 的大小写写法仍照常识别（如只有 Credit 的课程按该值读取）；不指向任何
// 记录字段的未知键不在此列，继续按未知字段拒绝。
//
// JSON 字符串的原始内容必须能还原为合法 Unicode 文字：字符串中直接写入的
// 字节不是合法 UTF-8，或 \uXXXX 转义中出现未配对的高位/低位代理项（高位
// 代理项后没有紧跟低位代理项、孤立的低位代理项、两个高位代理项相连等），
// 整份文件都判为内容损坏——标准库会把这些内容静默替换成 U+FFFD，替换后的
// 编号或依据绝不能当成正常内容继续查询、核对或登记，哪怕问题只在一条已拒绝
// 免修的依据里或本次核对不涉及的课程名称里。检查只读不写：不替用户修补转义、
// 不删字符、不改动任何申请状态。合法文字不受影响：中文、直接写入的补充平面
// 字符、完整的高低代理项转义对、转义表达的控制字符，以及用户确实写入的
// “�”（U+FFFD）都按原样使用。
//
// 有效免修的依据校验与首次正常申请一致：任何状态为有效（approved）的免修，
// 其依据必须含有实际文字；依据为空，或全部由空白字符（空格、制表符、换行、
// 回车、全角空格 U+3000、不换行空格 U+00A0 等，允许混用）组成时，整份记录
// 按内容损坏拒绝读取，即使该要求另有通过修读也不例外。已拒绝申请的依据允许
// 为空或只有空白。检查只读不写：不会补填依据、不会改动免修状态，也不会修剪
// 含实际文字的依据中原有空白。
//
// 已拒绝（rejected）免修必须保留含实际文字的拒绝原因：reason 字段没有出现、
// 显式写成 JSON null、空字符串，或只含空白字符（空格、制表符、换行、回车、
// 全角空格 U+3000、不换行空格 U+00A0 等，允许混用），都算没有原因，整份记录
// 按内容损坏拒绝读取。被拒绝的申请必须能说明当时为什么没有生效，缺了原因的
// 文件不能作为正常学分记录继续使用：只要文件中有一份这样的申请就整份拒绝，
// 哪怕它不属于本次查询的学生，或其目标要求已另有通过修读、有效免修、照常能
// 算出学分，也不能跳过这份历史。字段名大小写与 Unicode 转义沿用既有识别规则
// （reason、Reason、REASON 及解码后等同的转义写法都指向同一字段），字段在
// 免修对象中的位置不影响结果。含实际文字的原因按原文保留（包括前后与中间的
// 空白），不要求固定措辞，也不根据当前课程要求重新判断旧申请；因依据为空被
// 拒绝的申请仍允许保留空依据。检查只读不写：不补写推测的原因、不删除申请、
// 不把状态改成有效。有效免修原本可以没有 reason，已撤销免修沿用既有读取与
// 核对行为，二者都不增加原因限制。
//
// 课程开放状态字段显式写成 JSON null（"open":null，open、Open、OPEN 及解码
// 后等同的 Unicode 转义写法都指向同一字段，字段在课程对象中的位置不影响
// 结果）时，整份记录按内容损坏拒绝读取。标准库把 null 解进普通 bool 不报错，
// 字段保持零值 false，未定状态会被读成明确停开，进而误拒新增修读，并在后续
// 保存时把 null 固化成 false；因此只要课程编号、名称、学分合法而开放状态
// 显式为空，就拒绝整份文件——该课程尚未被要求引用、本次只查看另一名学生
// 也不跳过它继续办理。true（开放）与 false（停开）仍是合法状态，停开课程
// 照常可以建立要求、已有修读照常提交成绩；字段完全省略时沿用既有读取规则，
// 本次不改动。课程名称、免修依据中的普通文字“null”（字符串值）不是状态空值；
// 最外层 null、空数组或空列表继续按各自既有规则读取。检查只读不写：不补填
// 状态、不删除课程、不另存部分记录。
func Load(path string) (s *Store, existed bool, err error) {
	f, err := os.Open(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return NewStore(), false, nil
		}
		return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
	}
	defer f.Close()

	fi, err := f.Stat()
	if err != nil {
		return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
	}
	if fi.Size() == 0 {
		return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
	}

	raw, err := io.ReadAll(f)
	if err != nil {
		return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
	}

	// 先按原始字节检查 JSON 字符串能否还原为合法 Unicode 文字。标准库解码
	// 会把非法 UTF-8 字节与未配对的高/低位代理项转义静默替换成 U+FFFD，
	// 替换后的学生编号、课程名称或免修依据绝不能当成正常内容继续办理业务
	// （两个本来不同的编号可能被替换成同一个），这样的文件整份判为内容
	// 损坏，哪怕问题只在一条已拒绝免修的依据里或本次核对不涉及的课程名称
	// 里。检查只读不写：不修补转义、不删字符、不改动申请状态。
	if err := scanStringUnicode(raw); err != nil {
		return nil, true, fmt.Errorf(
			"记录文件 %s 内容损坏（包含无效的 Unicode 文字：%v），未做任何修改",
			path, err)
	}

	// 先在 token 流上检查同一 JSON 对象内的字段归属。标准库直接解进结构
	// 体时会用后一个重复键静默覆盖前一个，而且结构体字段按大小写不敏感
	// 匹配 json 标签：同一门课程写了 "credit":4 与 "Credit":9（4 会被
	// 9 悄悄顶替，两个键颠倒又变成 4），最外层同时写 courses 与 COURSES
	// （后一份即使是空数组也会盖掉前一份），修读里的 student 与 Student
	// 都无法明确说明字段归属。这样的记录必须整份判为损坏，绝不能据此
	// 核对或办理——即使冲突只在本次查询没有涉及的课程或免修历史里。
	// 仅扫描第一份完整值，其后内容仍由下方的“完整记录之后不得有多余
	// 内容”检查处理。
	var dupErr *duplicateFieldError
	if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
		if dupErr.first == dupErr.second {
			return nil, true, fmt.Errorf(
				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
				path, dupErr.field)
		}
		return nil, true, fmt.Errorf(
			"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定），未做任何修改",
			path, dupErr.first, dupErr.second, dupErr.field)
	}

	// 显式的 "open":null 必须在结构体解码之前拦截。标准库把 JSON null 解进
	// 非指针 bool 时既不报错也不改字段，零值 false 会被原样保留——于是“开放
	// 状态未确定”的课程被读成“停开”：课程列表显示停开、新增修读被误拒，
	// 之后任何一次需要保存的操作还会把未定状态写成明确的 false。因此只要
	// 课程对象显式给出开放状态字段（open/Open/OPEN 及解码后等同的 Unicode
	// 转义写法，位置不限）而值是 null，整份文件判为内容损坏，哪怕该课程
	// 尚未被任何要求引用、本次只查看另一名学生也不跳过它继续办理。扫描只读
	// 不写：不补填状态、不删除课程；字段省略时的既有读取规则（按零值处理）
	// 不在此列，课程名称、免修依据中的普通文字“null”也不是状态空值。
	var openNullErr *nullCourseOpenError
	if err := scanNullCourseOpen(bytes.NewReader(raw)); errors.As(err, &openNullErr) {
		return nil, true, fmt.Errorf(
			"记录文件 %s 内容损坏（%v），未做任何修改", path, err)
	}

	// 已拒绝免修必须保留含实际文字的拒绝原因，同样要在结构体解码之前拦截：
	// 解码后的 Waiver.Reason 是普通 string，字段没有出现、"reason":null 与
	// "reason":"" 都会变成零值空串，无法区分，而这三种（连同只含空白的字符
	// 串）本次都要拒绝。被拒绝的申请必须能说明当时为什么没有生效；缺了原因，
	// check 列出的申请就没有解释，随后登记其他记录还会把这份不完整历史继续
	// 保存。只要文件中有一份这样的已拒绝申请就整份判为内容损坏——哪怕它不
	// 属于本次查询的学生，或其目标要求已另有通过修读、有效免修、照常能算出
	// 学分，也不能跳过这份历史继续办理。扫描只读不写：不补写推测的原因、不
	// 删除申请、不把状态改成有效。有效免修原本可以没有 reason，已撤销免修
	// 沿用既有读取与核对行为，两者都不受此限制。
	var missingReasonErr *missingRejectReasonError
	if err := scanRejectedWaiverReasons(bytes.NewReader(raw)); errors.As(err, &missingReasonErr) {
		return nil, true, fmt.Errorf(
			"记录文件 %s 内容损坏（%v），未做任何修改", path, err)
	}

	var data fileData
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&data); err != nil {
		return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
	}
	// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
	// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
	// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
	// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
	// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
	// 片段。这些一律视为文件损坏。
	var extra json.RawMessage
	switch err := dec.Decode(&extra); {
	case errors.Is(err, io.EOF):
		// 唯一一份完整记录之后只有空白，符合格式。
	case err == nil:
		return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
	default:
		return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
	}

	s = NewStore()
	if err := s.loadData(&data); err != nil {
		return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
	}
	return s, true, nil
}

// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
func (s *Store) loadData(d *fileData) error {
	if d.Version != recordVersion {
		return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
	}

	// 课程
	for _, c := range d.Courses {
		if c == nil {
			return errors.New("存在空的课程记录")
		}
		if c.ID == "" {
			return errors.New("存在没有编号的课程")
		}
		if c.Name == "" {
			return fmt.Errorf("课程 %s 没有名称", c.ID)
		}
		if c.Credit <= 0 {
			return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
		}
		if _, dup := s.courseByID[c.ID]; dup {
			return fmt.Errorf("课程编号 %s 重复", c.ID)
		}
		s.courses = append(s.courses, c)
		s.courseByID[c.ID] = c
	}

	// 学生
	for _, st := range d.Students {
		if st == nil || st.ID == "" {
			return errors.New("存在没有编号的学生记录")
		}
		if _, dup := s.studentByID[st.ID]; dup {
			return fmt.Errorf("学生编号 %s 重复", st.ID)
		}
		s.students = append(s.students, st)
		s.studentByID[st.ID] = st
	}

	// 要求
	for _, r := range d.Requirements {
		if r == nil {
			return errors.New("存在空的课程要求记录")
		}
		if r.StudentID == "" || r.ID == "" {
			return errors.New("存在缺少学生编号或要求编号的课程要求")
		}
		if _, ok := s.studentByID[r.StudentID]; !ok {
			return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
		}
		if _, ok := s.courseByID[r.CourseID]; !ok {
			return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
				r.StudentID, r.ID, r.CourseID)
		}
		key := reqKey(r.StudentID, r.ID)
		if _, dup := s.reqByKey[key]; dup {
			return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
		}
		dk := dupKey(r.StudentID, r.CourseID)
		if other, dup := s.reqByDup[dk]; dup {
			return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
				r.StudentID, r.CourseID, other, r.ID)
		}
		s.requirements = append(s.requirements, r)
		s.reqByKey[key] = r
		s.reqByDup[dk] = r.ID
	}

	// 修读
	usedSeq := map[int]bool{}
	for _, e := range d.Enrollments {
		if e == nil {
			return errors.New("存在空的修读记录")
		}
		if e.StudentID == "" || e.ID == "" {
			return errors.New("存在缺少学生编号或修读编号的修读记录")
		}
		if _, ok := s.studentByID[e.StudentID]; !ok {
			return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
		}
		r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
		if r == nil {
			return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
				e.StudentID, e.ID, e.ReqID)
		}
		if e.Term == "" {
			return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
		}
		switch e.Result {
		case Enrolled, Passed, Failed:
		default:
			return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
		}
		if e.Result == Enrolled {
			if e.ResultSeq != 0 {
				return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
			}
		} else {
			if e.ResultSeq <= 0 {
				return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
			}
			if usedSeq[e.ResultSeq] {
				return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
			}
			usedSeq[e.ResultSeq] = true
		}
		key := reqKey(e.StudentID, e.ID)
		if _, dup := s.enrByKey[key]; dup {
			return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
		}
		s.enrollments = append(s.enrollments, e)
		s.enrByKey[key] = e
	}

	// 免修（被拒绝的申请允许指向当时不存在的要求、依据也可以为空；
	// 已撤销的申请则必须保留一份曾经有效的申请所必需的信息）
	approvedReq := map[ownerKey]string{} // (student, req) -> waiverID
	for _, w := range d.Waivers {
		if w == nil {
			return errors.New("存在空的免修记录")
		}
		if w.StudentID == "" || w.ID == "" {
			return errors.New("存在缺少学生编号或免修编号的免修记录")
		}
		if _, ok := s.studentByID[w.StudentID]; !ok {
			return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
		}
		switch w.Status {
		case WaiverApproved, WaiverRejected, WaiverRevoked:
		default:
			return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
		}
		switch w.Status {
		case WaiverApproved:
			// 有效免修的依据校验与首次正常申请完全一致：依据必须含有实际
			// 文字，空串或全部由空白字符（空格、制表符、换行、全角空格
			// U+3000、不换行空格 U+00A0 等，含混用）组成都按内容损坏
			// 拒绝整份记录——这样的“有效免修”无法有据可查，即使该要求
			// 另有通过修读也不能放过。检查只读不写，绝不修剪或改写文件
			// 中已保存的依据原文，也不把它降级成已拒绝/已撤销。
			if blankBasis(w.Basis) {
				return fmt.Errorf("学生 %s 的有效免修 %s 缺少依据（依据为空或全部为空白字符）",
					w.StudentID, w.ID)
			}
			rk := reqKey(w.StudentID, w.ReqID)
			if s.reqByKey[rk] == nil {
				return fmt.Errorf("有效免修 %s 指向的要求 %s 不存在或不属于该学生", w.ID, w.ReqID)
			}
			if other, dup := approvedReq[rk]; dup {
				return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
					w.StudentID, w.ReqID, other, w.ID)
			}
			approvedReq[rk] = w.ID
		case WaiverRevoked:
			// 撤销只取消免修对课程要求的满足作用，不能把缺少原依据、
			// 失去要求归属的记录变成合法历史：目标要求必须真实存在于
			// 该免修所属学生名下（同号要求只在其他学生名下不算），
			// 原依据必须含有非空白内容（空白口径与有效免修一致，全角
			// 空格、不换行空格等同样不算实际依据）。检查只读不写，
			// 依据中有实际文字时原有空白一律保留，绝不为了通过检查
			// 改写保存下来的材料内容。失效历史不参与有效免修的唯一
			// 性限制。
			if s.reqByKey[reqKey(w.StudentID, w.ReqID)] == nil {
				return fmt.Errorf("学生 %s 的已撤销免修 %s 目标要求无效（要求 %s 不存在于该学生名下）",
					w.StudentID, w.ID, w.ReqID)
			}
			if blankBasis(w.Basis) {
				return fmt.Errorf("学生 %s 的已撤销免修 %s 原依据为空", w.StudentID, w.ID)
			}
		case WaiverRejected:
			// 已拒绝申请必须保留含实际文字的拒绝原因（字段缺失、null、空串
			// 或全部为空白字符都算没有原因）。正常读取时这一点已由
			// scanRejectedWaiverReasons 在结构体解码之前保证（缺失与 null 经
			// 解码都会变成空串，无法再区分，所以必须在扫描阶段拦截）；这里
			// 再兜底一次，使“拒绝历史必有原因”成为 loadData 自身的不变量，
			// 直接构造 fileData 调用本函数也绕不过去。检查只读不写：不补写
			// 推测的原因、不删除申请、不把状态改成有效。
			if strings.TrimSpace(w.Reason) == "" {
				return fmt.Errorf("学生 %s 的已拒绝免修 %s 缺少拒绝原因（原因为空或全部为空白字符）",
					w.StudentID, w.ID)
			}
		}
		key := reqKey(w.StudentID, w.ID)
		if _, dup := s.waiverByKey[key]; dup {
			return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
		}
		s.waivers = append(s.waivers, w)
		s.waiverByKey[key] = w
	}

	if d.NextResultSeq < 0 {
		return errors.New("结果提交序号计数器为负数")
	}
	for seq := range usedSeq {
		if seq > d.NextResultSeq {
			return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
		}
	}
	s.nextResultSeq = d.NextResultSeq
	return nil
}

// invalidTextError 表示待保存记录中含有无法原样写入文件的文字：某个字符串
// 字段不是合法 UTF-8。category 指出记录类别（课程、学生、课程要求、修读、
// 免修），id 是该条记录的编号（仅用于定位，编号本身也可能就是问题所在，
// 按原始字节呈现），field 指出具体字段。
type invalidTextError struct {
	category string
	id       string
	field    string
}

func (e *invalidTextError) Error() string {
	return fmt.Sprintf(
		"%s记录（编号 %s）的字段“%s”含无法原样保存的非法 UTF-8 文字",
		e.category, e.id, e.field)
}

// validateSaveText 检查全部待写入记录的字符串字段是否都是合法 UTF-8。
//
// 背景：encoding/json 在序列化时会把字符串里的非法 UTF-8 字节静默替换成
// U+FFFD（“�”）却照常返回成功。若直接保存，免修依据会被改写，两个本来
// 不同的学生编号还可能被替换成同一个编号，让原本可读的记录文件变成编号
// 重复的损坏文件，而命令却提示成功。因此凡是要写入文件的文字——课程、
// 学生、课程要求、修读、免修的编号、名称、学期、依据、原因等——都必须先
// 通过本检查，任何一个字段不合法就拒绝整次保存。
//
// 检查只读不补：绝不替换、清空或修补任何原始字符串，也不删除出问题的
// 那条历史（即使它只是一条已拒绝或已撤销的免修），更不会跳过该字段只存
// 其他记录。合法文字不受影响：中文、补充平面字符、用户确实输入的“�”
// （U+FFFD）都是合法 UTF-8；编号中合法的控制字符与免修依据中原有的空白
// 也原样保留。命令行里字面出现的“\uD800”只是反斜线加普通字母数字，是
// 合法 ASCII 文字，不按记录文件中的 Unicode 转义处理。
func (s *Store) validateSaveText() error {
	for _, c := range s.courses {
		if c == nil {
			continue
		}
		if err := checkSaveText("课程", c.ID, "编号", c.ID); err != nil {
			return err
		}
		if err := checkSaveText("课程", c.ID, "名称", c.Name); err != nil {
			return err
		}
	}
	for _, st := range s.students {
		if st == nil {
			continue
		}
		if err := checkSaveText("学生", st.ID, "编号", st.ID); err != nil {
			return err
		}
	}
	for _, r := range s.requirements {
		if r == nil {
			continue
		}
		if err := checkSaveText("课程要求", r.ID, "编号", r.ID); err != nil {
			return err
		}
		if err := checkSaveText("课程要求", r.ID, "学生编号", r.StudentID); err != nil {
			return err
		}
		if err := checkSaveText("课程要求", r.ID, "课程编号", r.CourseID); err != nil {
			return err
		}
	}
	for _, e := range s.enrollments {
		if e == nil {
			continue
		}
		if err := checkSaveText("修读", e.ID, "编号", e.ID); err != nil {
			return err
		}
		if err := checkSaveText("修读", e.ID, "学生编号", e.StudentID); err != nil {
			return err
		}
		if err := checkSaveText("修读", e.ID, "要求编号", e.ReqID); err != nil {
			return err
		}
		if err := checkSaveText("修读", e.ID, "学期", e.Term); err != nil {
			return err
		}
		if err := checkSaveText("修读", e.ID, "结果", string(e.Result)); err != nil {
			return err
		}
	}
	for _, w := range s.waivers {
		if w == nil {
			continue
		}
		if err := checkSaveText("免修", w.ID, "编号", w.ID); err != nil {
			return err
		}
		if err := checkSaveText("免修", w.ID, "学生编号", w.StudentID); err != nil {
			return err
		}
		if err := checkSaveText("免修", w.ID, "要求编号", w.ReqID); err != nil {
			return err
		}
		if err := checkSaveText("免修", w.ID, "依据", w.Basis); err != nil {
			return err
		}
		if err := checkSaveText("免修", w.ID, "状态", string(w.Status)); err != nil {
			return err
		}
		if err := checkSaveText("免修", w.ID, "原因", w.Reason); err != nil {
			return err
		}
	}
	return nil
}

// duplicateResultSeqError 表示待保存记录中有两份不同修读的已提交成绩共用同一个
// 正整数结果提交顺序编号。seq 是冲突的编号；first/second 各用完整学生编号与
// 修读编号共同指明冲突双方，便于调用方分辨不同学生名下编号相同的修读（例如
// 两名学生各有一份 e1）。顺序按修读在记录中的先后确定，first 先出现。
type duplicateResultSeqError struct {
	seq           int
	firstStudent  string
	firstEnr      string
	secondStudent string
	secondEnr     string
}

func (e *duplicateResultSeqError) Error() string {
	return fmt.Sprintf(
		"成绩提交顺序编号 %d 被两份不同修读的已提交成绩共用：学生 %s 的修读 %s 与学生 %s 的修读 %s",
		e.seq, e.firstStudent, e.firstEnr, e.secondStudent, e.secondEnr)
}

// validateResultSeqUniqueness 检查全部已提交成绩的结果提交顺序编号互不相同。
//
// 顺序编号刻画的是整份记录中每次“首次提交成绩”的先后，通过与未通过都占用
// 一次编号，它不按学生、课程要求或学期各自编号：同一学生的重复修读、不同
// 要求下的独立提交、不同学生的独立修读，只要两份不同修读的已提交成绩共用
// 同一个正整数编号，写出的文件随后就会被 Load 判为内容损坏。因此这样的
// 待保存记录必须在序列化与临时文件之前整次拒绝保存——绝不删修读、不替
// 调用方重新编号、不清成绩或免修历史，也不能用这份记录替换掉原本可用的
// 记录文件。
//
// 尚未提交结果、仍处于选课状态的修读沿用编号 0，多份并存不构成重复，本
// 检查直接跳过它们；判定只看已提交成绩携带的正整数编号，因此已提交编号有
// 空缺（不连续）合法，冲突记录之间夹着其他正常成绩或免修也不能掩盖冲突。
// 以修读在记录中的先后取最先相撞的一对，结果确定且与 map 遍历顺序无关。
func (s *Store) validateResultSeqUniqueness() error {
	first := map[int]*Enrollment{}
	for _, e := range s.enrollments {
		if e == nil || e.Result == Enrolled {
			// 选课记录的编号一律是 0，多份并存正常，不参与重复判定。
			continue
		}
		if e.ResultSeq <= 0 {
			// 本规则只管“正整数顺序编号被共用”：非正编号不是这里的判定对象。
			continue
		}
		if prev := first[e.ResultSeq]; prev != nil {
			return &duplicateResultSeqError{
				seq:           e.ResultSeq,
				firstStudent:  prev.StudentID,
				firstEnr:     prev.ID,
				secondStudent: e.StudentID,
				secondEnr:     e.ID,
			}
		}
		first[e.ResultSeq] = e
	}
	return nil
}

// checkSaveText 校验单个待保存字段的文字是否为合法 UTF-8。
func checkSaveText(category, id, field, value string) error {
	if !utf8.ValidString(value) {
		return &invalidTextError{category: category, id: id, field: field}
	}
	return nil
}

// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
// 避免写到一半时损坏原文件。
//
// 写入前先做两项检查：
//
// 一是全部待保存字符串都必须是合法 UTF-8：标准库序列化会把非法字节静默
// 替换成 U+FFFD，因此含非法文字的数据绝不能进入序列化与临时文件阶段。
// 校验失败时整次保存直接返回错误——不创建/不改动目标文件（目标原本不
// 存在时也不会留下新记录文件或临时文件），不替换、清空或修补待保存记录
// 中的任何原始字符串，即使问题只出现在一条已拒绝或已撤销免修的字段里。
//
// 二是全部已提交成绩的结果提交顺序编号互不相同：顺序编号表示整份记录中
// 每次首次提交成绩的先后，通过与未通过都占用一次编号，不按学生、要求或
// 学期各自编号。两份不同修读（同一学生的重复修读或不同学生的独立修读，
// 无论修读编号、要求编号、学期是否相同，也无论两条记录是否相邻）的已提交
// 成绩共用同一个正整数编号时，写出的文件随后必然被 Load 判为内容损坏，
// 因此直接拒绝整次保存：错误点名目标文件、重复编号及冲突双方（完整学生
// 编号 + 修读编号），已有文件全部内容原样保留，目标原本不存在时不创建
// 记录文件也不遗留临时文件；待保存的内存记录同样原样保留——不删修读、
// 不替调用方调整顺序、不清成绩或免修历史。仍是选课、尚未提交结果的修读
// 沿用编号 0，多份并存不构成重复；已提交编号有空缺（不连续）仍合法。
func (s *Store) Save(path string) (err error) {
	if err := s.validateSaveText(); err != nil {
		return fmt.Errorf("记录中存在无法原样保存的文字，拒绝写入 %s：%w", path, err)
	}
	if err := s.validateResultSeqUniqueness(); err != nil {
		return fmt.Errorf("记录中的成绩提交顺序编号冲突，拒绝写入 %s，已有文件保持原样：%w", path, err)
	}
	data := fileData{
		Version:       recordVersion,
		Courses:       s.courses,
		Students:      s.students,
		Requirements:  s.requirements,
		Enrollments:   s.enrollments,
		Waivers:       s.waivers,
		NextResultSeq: s.nextResultSeq,
	}
	buf, err := json.MarshalIndent(&data, "", "  ")
	if err != nil {
		return fmt.Errorf("无法序列化记录：%w", err)
	}
	buf = append(buf, '\n')

	dir := filepath.Dir(path)
	if dir == "" {
		dir = "."
	}
	tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
	if err != nil {
		return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
	}
	tmpName := tmp.Name()
	defer func() {
		if err != nil {
			tmp.Close()
			os.Remove(tmpName)
		}
	}()
	if _, err = tmp.Write(buf); err != nil {
		return fmt.Errorf("写入记录文件失败：%w", err)
	}
	if err = tmp.Sync(); err != nil {
		return fmt.Errorf("写入记录文件失败：%w", err)
	}
	if err = tmp.Close(); err != nil {
		return fmt.Errorf("写入记录文件失败：%w", err)
	}
	if err = os.Chmod(tmpName, 0o600); err != nil {
		return fmt.Errorf("设置记录文件权限失败：%w", err)
	}
	if err = os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
	}
	return nil
}

// Package credit 实现本地课程学分与免修的登记、持久化与核对。
//
// 基本对象：
//   - 学生（Student）：以唯一编号登记；
//   - 课程（Course）：唯一编号、名称、正整数学分，初始开放，可停开/恢复；
//   - 课程要求（Requirement）：属于某名学生，编号在该学生名下唯一，指向一门课程；
//   - 修读（Enrollment）：属于某名学生的一项要求，记录学期与编号，结果为
//     选课/通过/未通过；
//   - 免修（Waiver）：明确指向该学生的一项要求，带编号与非空依据，状态为
//     有效/已拒绝/已撤销。
//
// 所有“重复登记相同内容”的操作都幂等：返回原记录、不新增数据；内容冲突的
// 重复请求一律拒绝并保留原记录。
package credit

import (
	"errors"
	"fmt"
	"math"
	"strings"
)

// Result 是修读结果。
type Result string

const (
	// Enrolled 已选课、尚未有结果，不计学分。
	Enrolled Result = "enrolled"
	// Passed 通过。
	Passed Result = "passed"
	// Failed 未通过，不计学分。
	Failed Result = "failed"
)

// WaiverStatus 是免修申请的状态。
type WaiverStatus string

const (
	// WaiverApproved 有效免修：满足对应要求并获得课程学分。
	WaiverApproved WaiverStatus = "approved"
	// WaiverRejected 已拒绝：申请内容与拒绝原因保留在免修历史中。
	WaiverRejected WaiverStatus = "rejected"
	// WaiverRevoked 已撤销：原依据保留，要求按修读情况重新判定。
	WaiverRevoked WaiverStatus = "revoked"
)

// Course 课程：编号唯一，学分为正整数。
type Course struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Credit int    `json:"credit"`
	Open   bool   `json:"open"`
}

// Student 学生：只有唯一编号。
type Student struct {
	ID string `json:"id"`
}

// Requirement 课程要求：在所属学生名下编号唯一，指向一门已登记课程。
type Requirement struct {
	ID        string `json:"id"`
	StudentID string `json:"student"`
	CourseID  string `json:"course"`
}

// Enrollment 修读：属于某名学生的一项要求，编号在该学生名下唯一。
type Enrollment struct {
	ID        string `json:"id"`
	StudentID string `json:"student"`
	ReqID     string `json:"req"`
	Term      string `json:"term"`
	Result    Result `json:"result"`
	// ResultSeq 是首次提交结果的先后序号，用于确定“最先提交的通过记录”。
	ResultSeq int `json:"resultSeq,omitempty"`
}

// Waiver 免修申请。被拒绝或撤销后记录仍保留在免修历史中。
type Waiver struct {
	ID        string       `json:"id"`
	StudentID string       `json:"student"`
	ReqID     string       `json:"req"`
	Basis     string       `json:"basis"`
	Status    WaiverStatus `json:"status"`
	// Reason 记录拒绝原因或撤销原因。
	Reason string `json:"reason,omitempty"`
}

// Store 是全部记录的内存集合，零值即可用。
type Store struct {
	courses      []*Course
	students     []*Student
	requirements []*Requirement
	enrollments  []*Enrollment
	waivers      []*Waiver

	courseByID    map[string]*Course
	studentByID   map[string]*Student
	reqByKey      map[ownerKey]*Requirement // (student, reqID)
	reqByDup      map[ownerKey]string       // (student, course) -> reqID
	enrByKey      map[ownerKey]*Enrollment  // (student, enrID)
	waiverByKey   map[ownerKey]*Waiver      // (student, waiverID)
	nextResultSeq int
	// dirty 记录自加载以来是否发生过需要落盘的变更（新建被拒绝的免修也算）。
	dirty bool
}

// ownerKey 是“所属学生编号 + 该学生名下编号”的复合键。两部分各自按完整
// 文字参与比较，因此要求是否存在必须以所属学生和编号都完全一致为准。
// 不能用 student + "\x00" + id 之类的字符串拼接：JSON 解码后的编号本身
// 允许包含 U+0000 等任意字符，拼接键会把 ("s","x\x00r") 与 ("s\x00x","r")
// 两项不同学生的记录混成同一键，导致合法文件被判重复或免修借用他人要求。
type ownerKey struct {
	student string
	id      string
}

func reqKey(student, id string) ownerKey { return ownerKey{student, id} }
func dupKey(student, course string) ownerKey {
	return ownerKey{student, course}
}

// blankBasis 报告一份免修依据是否不含任何实际文字：空字符串，或全部由空白
// 字符组成。空白按 Unicode 判定，除空格、制表符、换行、回车外还包括全角
// 空格（U+3000）、不换行空格（U+00A0）等，混合使用这些字符仍算没有依据。
//
// 该判定只用于读取校验，绝不修剪或改写已保存的依据原文——依据中含有实际
// 文字时，其前后与中间原有的空白必须原样保留在免修历史中。
func blankBasis(basis string) bool {
	return strings.TrimSpace(basis) == ""
}

func newStore() *Store {
	s := &Store{}
	s.resetIndexes()
	return s
}

func (s *Store) resetIndexes() {
	s.courseByID = map[string]*Course{}
	s.studentByID = map[string]*Student{}
	s.reqByKey = map[ownerKey]*Requirement{}
	s.reqByDup = map[ownerKey]string{}
	s.enrByKey = map[ownerKey]*Enrollment{}
	s.waiverByKey = map[ownerKey]*Waiver{}
}

// ensureIndexes 在首次写入前惰性建立索引，使 Store 零值即可用：直接声明的
// 零值记录集合（索引均为 nil）在第一次登记时自动补齐索引，行为与
// NewStore 创建的空集合一致，调用者无需额外初始化。索引只会整体建立或
// 整体为 nil，因此检查其中一个即可。只读查询本就可以安全读取 nil 索引，
// 无需调用本函数。
func (s *Store) ensureIndexes() {
	if s.courseByID == nil {
		s.resetIndexes()
	}
}

// NewStore 返回空记录集。
func NewStore() *Store { return newStore() }

// Dirty 报告自加载以来是否发生过需要落盘的变更。
// 被拒绝但要保留在免修历史中的申请也计为变更；纯幂等返回与只读核对不计。
func (s *Store) Dirty() bool { return s.dirty }

// ---------- 查询 ----------

// Course 按编号返回课程；不存在返回 nil。
func (s *Store) Course(id string) *Course { return s.courseByID[id] }

// Courses 按登记顺序返回全部课程。
func (s *Store) Courses() []*Course { return append([]*Course(nil), s.courses...) }

// Student 按编号返回学生；不存在返回 nil。
func (s *Store) Student(id string) *Student { return s.studentByID[id] }

// Students 按登记顺序返回全部学生。
func (s *Store) Students() []*Student { return append([]*Student(nil), s.students...) }

// Requirement 返回某学生名下的要求；不存在（包括要求属于其他学生）返回 nil。
func (s *Store) Requirement(student, reqID string) *Requirement {
	return s.reqByKey[reqKey(student, reqID)]
}

// Requirements 返回某学生的全部要求（按登记顺序）；学生不存在返回 nil。
func (s *Store) Requirements(student string) []*Requirement {
	if _, ok := s.studentByID[student]; !ok {
		return nil
	}
	var out []*Requirement
	for _, r := range s.requirements {
		if r.StudentID == student {
			out = append(out, r)
		}
	}
	return out
}

// AllRequirements 按登记顺序返回全部要求。
func (s *Store) AllRequirements() []*Requirement {
	return append([]*Requirement(nil), s.requirements...)
}

// Enrollment 返回某学生名下的修读；不存在返回 nil。
func (s *Store) Enrollment(student, id string) *Enrollment {
	return s.enrByKey[reqKey(student, id)]
}

// Enrollments 返回某学生的全部修读（按登记顺序）；学生不存在返回 nil。
func (s *Store) Enrollments(student string) []*Enrollment {
	if _, ok := s.studentByID[student]; !ok {
		return nil
	}
	var out []*Enrollment
	for _, e := range s.enrollments {
		if e.StudentID == student {
			out = append(out, e)
		}
	}
	return out
}

// Waiver 返回某学生名下的免修申请；不存在返回 nil。
func (s *Store) Waiver(student, id string) *Waiver {
	return s.waiverByKey[reqKey(student, id)]
}

// Waivers 返回某学生的全部免修历史（按申请顺序）；学生不存在返回 nil。
func (s *Store) Waivers(student string) []*Waiver {
	if _, ok := s.studentByID[student]; !ok {
		return nil
	}
	var out []*Waiver
	for _, w := range s.waivers {
		if w.StudentID == student {
			out = append(out, w)
		}
	}
	return out
}

// ---------- 学生 ----------

// AddStudent 登记学生。编号已存在时原样返回已有学生且 action=existed（幂等）。
//
// 学生编号按用户给出的完整文字参与查找与保存，前后空白（普通空格、制表符、
// 全角空格 U+3000、不换行空格 U+00A0 等）也是编号内容，绝不修剪：记录文件
// 可以合法保存 “s1” 与 “ s1 ” 两名独立学生，登记与重复判断必须命中编号
// 完全一致的那一名，并保留编号原文。文件里只有 “s1” 时提交 “ s1 ” 一律
// 新建，绝不借用去掉空白后能碰上的另一名学生的课程要求、修读、免修或学分；
// 再次提交某个完整编号时只判断对应学生：命中则返回原记录（幂等），不新增
// 副本、不改动记录文件，也不移动或合并两名学生各自名下编号相同的要求、
// 修读与免修历史。已有合法文件中的带空白编号继续按原文使用，登记不能把
// 它们改名，也不能为匹配输入重写其他记录的学生归属。
// 编号为空字符串，或全部由空白字符组成（普通空格、制表符、全角空格、
// 不换行空格等，允许混用）时直接拒绝，不创建学生；含实际文字的编号原样
// 保存。这与登记课程要求、选课、提交成绩、免修、核对、查询使用的对象
// 完全一致。
func (s *Store) AddStudent(id string) (st *Student, action Action, err error) {
	s.ensureIndexes()
	if id == "" {
		return nil, "", errors.New("学生编号不能为空")
	}
	if strings.TrimSpace(id) == "" {
		return nil, "", errors.New("学生编号不能为空")
	}
	if existing := s.studentByID[id]; existing != nil {
		return existing, ActionExisted, nil
	}
	st = &Student{ID: id}
	s.students = append(s.students, st)
	s.studentByID[id] = st
	s.dirty = true
	return st, ActionCreated, nil
}

// ---------- 课程 ----------

// Action 描述登记类操作相对已有记录做了什么。
type Action string

const (
	// ActionCreated 新建了记录。
	ActionCreated Action = "created"
	// ActionExisted 记录已存在且内容一致，原样返回（幂等）。
	ActionExisted Action = "existed"
	// ActionUpdated 记录已存在，本次在允许范围内更新了内容。
	ActionUpdated Action = "updated"
)

// AddCourse 登记课程，学分为正整数，新课程初始开放。
// 编号已存在且名称、学分完全相同时原样返回（幂等），停开/开放状态不变。
// 编号相同但学分不同：该课程尚未被任何课程要求引用时允许修改并保持开放
// 状态；已经被要求引用的课程不能修改学分，请求被拒绝且课程保持不变。
//
// 课程编号按用户给出的完整文字参与匹配与保存，前后空白（普通空格、制表符、
// 全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存 “c1” 与 “ c1 ”
// 两门独立课程，登记与重复判断必须命中编号完全一致的那一门，并保留编号原文。
// 完整编号找不到时一律新建，绝不借用去掉空白后能碰上的另一门课程的名称、
// 学分或停开/开放状态；再次提交某个完整编号时只判断对应课程：名称与学分
// 相同则返回原记录，内容不同仍按上述规则更新对应课程，不新增副本、不改动
// 另一门课程。学分锁定跟随实际命中的课程：只有要求引用了该完整编号的课程
// 时才禁止修改它的学分，另一门同号不同空白课程是否被引用与此无关。
// 编号为空字符串，或全部由空白字符组成（普通空格、制表符、全角空格等，
// 允许混用）时直接拒绝；含实际文字的编号原样保存。课程名称沿用现有输入
// 规则：前后空白不计入名称内容，修剪后为空则拒绝。
func (s *Store) AddCourse(id, name string, credit int) (c *Course, action Action, err error) {
	s.ensureIndexes()
	name = strings.TrimSpace(name)
	if id == "" {
		return nil, "", errors.New("课程编号不能为空")
	}
	if strings.TrimSpace(id) == "" {
		return nil, "", errors.New("课程编号不能只由空白字符组成")
	}
	if name == "" {
		return nil, "", errors.New("课程名称不能为空")
	}
	if credit <= 0 {
		return nil, "", fmt.Errorf("课程学分必须是正整数，得到 %d", credit)
	}
	if existing := s.courseByID[id]; existing != nil {
		if existing.Name == name && existing.Credit == credit {
			return existing, ActionExisted, nil
		}
		if existing.Credit != credit && s.courseReferenced(id) {
			return nil, "", fmt.Errorf(
				"课程 %s 已被课程要求引用，不能修改学分（原学分 %d），原记录保留",
				id, existing.Credit)
		}
		existing.Name = name
		existing.Credit = credit
		s.dirty = true
		return existing, ActionUpdated, nil
	}
	c = &Course{ID: id, Name: name, Credit: credit, Open: true}
	s.courses = append(s.courses, c)
	s.courseByID[id] = c
	s.dirty = true
	return c, ActionCreated, nil
}

// courseReferenced 报告课程是否被任何学生的课程要求引用。
func (s *Store) courseReferenced(id string) bool {
	for _, r := range s.requirements {
		if r.CourseID == id {
			return true
		}
	}
	return false
}

// SetCourseOpen 设置课程开放状态。课程不存在时报错；状态相同则原样返回。
func (s *Store) SetCourseOpen(id string, open bool) (*Course, error) {
	c := s.courseByID[id]
	if c == nil {
		return nil, fmt.Errorf("课程 %s 不存在", id)
	}
	if c.Open != open {
		c.Open = open
		s.dirty = true
	}
	return c, nil
}

// ---------- 课程要求 ----------

// AddRequirement 为学生登记一项指向课程的要求。
// 同一要求编号已存在且指向同一课程时返回原要求（幂等）；指向不同课程则拒绝。
// 同一学生就同一课程已有要求（即使编号不同）也拒绝。学生或课程不存在时拒绝。
//
// 学生编号、要求编号与课程编号按用户给出的完整文字参与匹配，前后空白
// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
// 合法保存 “s1” 与 “ s1 ” 两名学生、“c1” 与 “ c1 ” 两门课程、同一学生
// 名下 “r1” 与 “ r1 ” 两项要求，登记必须命中编号完全一致的学生与课程，
// 新要求也必须登记在完整编号的学生名下并保留完整编号。完整编号找不到
// 学生时报告学生不存在，完整编号找不到课程时报告课程不存在——即使去掉
// 空白能碰上另一名学生或另一门课程，也绝不借用那份记录，更不能自动创建
// 学生或课程。编号为空字符串时直接拒绝；要求编号只由空白字符组成时
// 不得建立。这与选课、免修、查询使用的对象完全一致：已有带空白编号的
// 合法记录继续按原样读取，不因登记而被改写、合并或重新解释。
// 课程是否停开不影响建立要求：新要求本身不带来学分，之后只有通过修读
// 或有效免修才能满足它。
func (s *Store) AddRequirement(studentID, reqID, courseID string) (r *Requirement, action Action, err error) {
	s.ensureIndexes()
	if studentID == "" || reqID == "" || courseID == "" {
		return nil, "", errors.New("学生编号、要求编号和课程编号不能为空")
	}
	if strings.TrimSpace(reqID) == "" {
		return nil, "", errors.New("要求编号不能只由空白字符组成")
	}
	if _, ok := s.studentByID[studentID]; !ok {
		return nil, "", fmt.Errorf("学生 %s 不存在，不能登记课程要求", studentID)
	}
	c := s.courseByID[courseID]
	if c == nil {
		return nil, "", fmt.Errorf("课程 %s 不存在，不能登记课程要求", courseID)
	}
	if existing := s.reqByKey[reqKey(studentID, reqID)]; existing != nil {
		if existing.CourseID != courseID {
			return nil, "", fmt.Errorf(
				"学生 %s 的要求编号 %s 已指向课程 %s，不能改指课程 %s",
				studentID, reqID, existing.CourseID, courseID)
		}
		return existing, ActionExisted, nil
	}
	if otherID, ok := s.reqByDup[dupKey(studentID, courseID)]; ok {
		return nil, "", fmt.Errorf(
			"学生 %s 已就课程 %s 建立要求 %s，不能重复建立", studentID, courseID, otherID)
	}
	r = &Requirement{ID: reqID, StudentID: studentID, CourseID: courseID}
	s.requirements = append(s.requirements, r)
	s.reqByKey[reqKey(studentID, reqID)] = r
	s.reqByDup[dupKey(studentID, courseID)] = reqID
	s.dirty = true
	return r, ActionCreated, nil
}

// ---------- 修读 ----------

// AddEnrollment 为学生的一项要求登记某学期的修读，初始状态为“选课”。
// 相同（学生、修读编号、要求、学期）的重复登记返回原记录（幂等）；
// 相同编号但要求或学期不同则拒绝；课程已停开时不能新增修读
// （已登记记录的重复提交仍按幂等返回原记录）。
//
// 学生编号、要求编号与修读编号按用户给出的完整文字参与匹配，前后空白
// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
// 要求、“e1” 与 “ e1 ” 两份修读，登记必须命中编号完全一致的对象，新
// 修读也必须登记在完整编号的学生与要求名下并保留完整编号。完整编号找
// 不到学生时报告学生不存在；学生存在但名下没有该完整要求编号时报告本人
// 名下没有该要求——即使去掉空白能碰上另一名学生或另一项要求，也绝不
// 借用那份记录，更不能把修读登记到别人名下。编号为空字符串时直接拒绝；
// 只由空白字符组成的修读编号不得建立。学期沿用现有输入规则：前后空白
// 不计入学期内容，修剪后为空则拒绝。
func (s *Store) AddEnrollment(studentID, reqID, term, enrID string) (e *Enrollment, action Action, err error) {
	s.ensureIndexes()
	term = strings.TrimSpace(term)
	if studentID == "" || reqID == "" || enrID == "" {
		return nil, "", errors.New("学生编号、要求编号和修读编号不能为空")
	}
	if strings.TrimSpace(enrID) == "" {
		return nil, "", errors.New("修读编号不能只由空白字符组成")
	}
	if term == "" {
		return nil, "", errors.New("学期不能为空")
	}
	if _, ok := s.studentByID[studentID]; !ok {
		return nil, "", fmt.Errorf("学生 %s 不存在，不能登记修读", studentID)
	}
	r := s.reqByKey[reqKey(studentID, reqID)]
	if r == nil {
		return nil, "", fmt.Errorf("学生 %s 名下不存在要求 %s，不能登记修读", studentID, reqID)
	}
	if existing := s.enrByKey[reqKey(studentID, enrID)]; existing != nil {
		if existing.ReqID != reqID || existing.Term != term {
			return nil, "", fmt.Errorf(
				"学生 %s 的修读编号 %s 已用于要求 %s、学期 %s，不能改为要求 %s、学期 %s",
				studentID, enrID, existing.ReqID, existing.Term, reqID, term)
		}
		return existing, ActionExisted, nil
	}
	c := s.courseByID[r.CourseID]
	if c == nil || !c.Open {
		return nil, "", fmt.Errorf("课程 %s 已停开，不能新增修读", r.CourseID)
	}
	e = &Enrollment{
		ID: enrID, StudentID: studentID, ReqID: reqID, Term: term, Result: Enrolled,
	}
	s.enrollments = append(s.enrollments, e)
	s.enrByKey[reqKey(studentID, enrID)] = e
	s.dirty = true
	return e, ActionCreated, nil
}

// SubmitResult 为修读提交通过/未通过结果。
// 重复提交相同结果返回原记录（幂等，不累加学分）；已提交结果后改提另一结果
// 一律拒绝并保留原记录。
//
// 首次提交结果会从全局递增计数器领取一个结果提交序号（ResultSeq），用于
// 记录多次提交的先后关系；通过与未通过都占用一次序号。计数器是整数类型
// int：当它已经达到该类型可表示的最大值（64 位环境下为
// 9223372036854775807）时，再递增必然回绕成负数并保存，会破坏整份记录
// （负序号、与原有序号的先后关系错乱、记录无法再正常读取）。因此计数已
// 到上限时，任何仍处于“选课”的修读都不能再首次提交结果：明确拒绝，不
// 改结果、不发序号、不标记变更；不会因该要求已有另一份通过修读或已有
// 有效免修而放行，也不能从小重新编号、借用历史空缺编号或改排已有成绩。
// 距上限恰好还差一时允许最后一次正常的首次提交，其先后关系照常保留；
// 未通过同样占用这最后一次机会且仍不计学分。已经提交过结果的修读不
// 需要新序号：重复提交相同结果仍幂等返回原记录，改提另一结果仍按冲突
// 规则拒绝。
//
// 学生编号与修读编号按用户给出的完整文字参与匹配，前后空白（普通空格、
// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
// “s1”与“ s1 ”两名学生、同一学生名下“e1”与“ e1 ”两份修读，提交
// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
// 学生存在但名下没有该完整修读编号时报告该修读不存在——即使去掉空白后
// 能碰上另一名学生或另一份修读，也绝不借用那份记录，更不能据此补建修读。
func (s *Store) SubmitResult(studentID, enrID string, result Result) (e *Enrollment, changed bool, err error) {
	if result != Passed && result != Failed {
		return nil, false, fmt.Errorf("修读结果只能是 %s 或 %s", Passed, Failed)
	}
	if _, ok := s.studentByID[studentID]; !ok {
		return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
	}
	e = s.enrByKey[reqKey(studentID, enrID)]
	if e == nil {
		return nil, false, fmt.Errorf("学生 %s 名下不存在修读 %s", studentID, enrID)
	}
	if e.Result == result {
		return e, false, nil
	}
	if e.Result != Enrolled {
		return nil, false, fmt.Errorf(
			"修读 %s 已提交结果“%s”，不能改为“%s”，原结果保留", enrID, zhResult(e.Result), zhResult(result))
	}
	// 首次提交必须领取新的结果序号。计数器已达 int 上限时不能再递增：
	// MaxInt+1 会静默回绕成 MinInt 并随修读落盘，随后连原有记录都无法
	// 正常读取。这里在改动任何状态之前拒绝，保持修读为选课、整份记录
	// 原样不变。是否还能提交只取决于计数器本身：不重新从小编号、不
	// 借用历史空缺编号，也不因该要求另有通过修读或有效免修而放行。
	if s.nextResultSeq >= math.MaxInt {
		return nil, false, fmt.Errorf(
			"学生 %s 的修读 %s 不能提交成绩：成绩提交顺序编号已用尽（已达本程序整数类型最大值 %d），无法提交新的成绩，原记录保留",
			studentID, enrID, math.MaxInt)
	}
	s.nextResultSeq++
	e.Result = result
	e.ResultSeq = s.nextResultSeq
	s.dirty = true
	return e, true, nil
}

// ---------- 免修 ----------

// ApplyWaiver 提交免修申请，依据必须含实际文字。
//
// 首次提交且内容合法：状态为有效（approved），action=created。
// 目标要求不存在（含要求属于其他学生）、依据不含实际文字、或该要求已有
// 有效免修：申请被拒绝，但申请内容与具体原因保留在该学生的免修历史中，
// 返回的申请状态为 rejected（仍属于新建记录，action=created）。
// 同一编号已存在：内容（要求、依据）完全相同时返回原申请及其结果
// （已拒绝/已撤销的申请不会因重试重新生效）；内容不同则拒绝且不改动原申请。
//
// 学生编号、要求编号与免修编号按用户给出的完整文字参与匹配，前后空白
// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
// 要求、“w1” 与 “ w1 ” 两份申请，提交必须命中编号完全一致的那一项，
// 申请也必须登记在完整编号的申请人名下。完整编号找不到学生时直接按业务
// 规则报错，不在任何学生名下新增历史；学生存在但名下没有该完整要求编号
// 时，即使去掉空白能碰上另一项要求，也绝不借用那份记录，而是按原规则在
// 申请人名下保存原要求编号、免修编号、依据原文与拒绝原因。编号为空字符串
// 时直接拒绝，不创建申请。依据含实际文字时其中的空白（包括前后空白）
// 原样保留；是否“没有依据”只按空白内容判定（见 blankBasis），绝不修剪
// 或改写依据原文。
func (s *Store) ApplyWaiver(studentID, reqID, waiverID, basis string) (w *Waiver, action Action, err error) {
	s.ensureIndexes()
	if studentID == "" || reqID == "" || waiverID == "" {
		return nil, "", errors.New("学生编号、要求编号和免修编号不能为空")
	}
	if _, ok := s.studentByID[studentID]; !ok {
		return nil, "", fmt.Errorf("学生 %s 不存在，不能申请免修", studentID)
	}
	if existing := s.waiverByKey[reqKey(studentID, waiverID)]; existing != nil {
		if existing.ReqID != reqID || existing.Basis != basis {
			return nil, "", fmt.Errorf(
				"学生 %s 的免修编号 %s 已存在（要求 %s、依据 %q），提交内容不同，拒绝修改",
				studentID, waiverID, existing.ReqID, existing.Basis)
		}
		return existing, ActionExisted, nil
	}

	w = &Waiver{ID: waiverID, StudentID: studentID, ReqID: reqID, Basis: basis}
	switch {
	case s.reqByKey[reqKey(studentID, reqID)] == nil:
		w.Status = WaiverRejected
		w.Reason = fmt.Sprintf("目标要求 %s 不存在或不属于该学生", reqID)
	case blankBasis(basis):
		w.Status = WaiverRejected
		w.Reason = "免修依据为空"
	default:
		if other := s.validWaiver(studentID, reqID); other != nil {
			w.Status = WaiverRejected
			w.Reason = fmt.Sprintf("该要求已有有效免修 %s", other.ID)
			break
		}
		w.Status = WaiverApproved
	}
	s.waivers = append(s.waivers, w)
	s.waiverByKey[reqKey(studentID, waiverID)] = w
	s.dirty = true
	return w, ActionCreated, nil
}

// validWaiver 返回某要求当前有效的免修。
func (s *Store) validWaiver(studentID, reqID string) *Waiver {
	for _, w := range s.waivers {
		if w.StudentID == studentID && w.ReqID == reqID && w.Status == WaiverApproved {
			return w
		}
	}
	return nil
}

// RevokeWaiver 撤销有效免修，原依据与撤销状态保留；reason 可填撤销原因。
// 重复撤销已撤销的免修：原样返回、changed=false，不改变结果。
// 撤销不存在的编号或撤销已被拒绝的申请：明确拒绝。
//
// 学生编号与免修编号按用户给出的完整文字参与匹配，前后空白（普通空格、
// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
// “s1”与“ s1 ”两名学生、同一学生名下“w1”与“ w1 ”两份免修，撤销
// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
// 学生存在但名下没有该完整免修编号时报告该免修不存在——即使去掉空白后
// 能碰上另一名学生或另一份免修，也绝不借用那份记录，更不能改写原编号、
// 合并申请或新增免修历史。撤销提示与免修历史一律使用实际命中的原编号。
func (s *Store) RevokeWaiver(studentID, waiverID, reason string) (w *Waiver, changed bool, err error) {
	reason = strings.TrimSpace(reason)
	if _, ok := s.studentByID[studentID]; !ok {
		return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
	}
	w = s.waiverByKey[reqKey(studentID, waiverID)]
	if w == nil {
		return nil, false, fmt.Errorf("学生 %s 名下不存在免修 %s，不能撤销", studentID, waiverID)
	}
	switch w.Status {
	case WaiverApproved:
		w.Status = WaiverRevoked
		if reason == "" {
			reason = "手动撤销"
		}
		w.Reason = reason
		s.dirty = true
		return w, true, nil
	case WaiverRevoked:
		return w, false, nil
	default:
		return nil, false, fmt.Errorf("免修 %s 已被拒绝，不能撤销（拒绝原因：%s）", waiverID, w.Reason)
	}
}

