293		e2.ResultSeq = 3
294		bad.nextResultSeq = 3 // 计数器随调用方改写后的最大编号保持一致（本检查不代劳）。
295		if err := bad.Save(path); err != nil {
296			t.Fatalf("调用方消除冲突后应能正常保存：%v", err)
297		}
298		reloaded, _, err := Load(path)
299		if err != nil {
300			t.Fatalf("消除冲突后的文件应可正常读取：%v", err)
301		}
302		if reloaded.Enrollment("s2", "e1").ResultSeq != 3 {
303			t.Fatal("消除冲突后的修改应原样落盘")
304		}
305	}
306	
307	// TestSaveDuplicateResultSeqDoesNotMutateMemory 拒绝保存不得改动待保存内存
308	// 记录的任何内容：修读、成绩、顺序编号、计数器、免修历史都保持提交时的样子。
309	func TestSaveDuplicateResultSeqDoesNotMutateMemory(t *testing.T) {
310		s := saveSeqTwoStudentStore(t)
311		if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
312			t.Fatal(err)
313		}
314		if _, _, err := s.SubmitResult("s2", "e1", Failed); err != nil {
315			t.Fatal(err)
316		}
317		if _, _, err := s.ApplyWaiver("s1", "r2", "w1", "竞赛获奖"); err != nil {
318			t.Fatal(err)
319		}
320		if w, _, err := s.ApplyWaiver("s1", "没有的要求", "wbad", "旧依据"); err != nil ||
321			w.Status != WaiverRejected {
322			t.Fatalf("被拒绝免修构造失败：%+v %v", w, err)
323		}
324		before := s.nextResultSeq
325		s.Enrollment("s1", "e1").ResultSeq = 7
326		s.Enrollment("s2", "e1").ResultSeq = 7
327	
328		path := filepath.Join(t.TempDir(), "records.json")
329		if err := s.Save(path); err == nil {
330			t.Fatal("共用顺序编号时必须拒绝保存")
331		}
332	
333		// 冲突双方原样保留，其他成绩、选课、计数器与全部免修历史也都不动。
334		if e := s.Enrollment("s1", "e1"); e == nil || e.Result != Passed || e.ResultSeq != 7 {
335			t.Fatalf("s1 的 e1 不得被改动，得到 %+v", e)
336		}
337		if e := s.Enrollment("s2", "e1"); e == nil || e.Result != Failed || e.ResultSeq != 7 {
338			t.Fatalf("s2 的 e1 不得被改动，得到 %+v", e)
339		}
340		if s.nextResultSeq != before {
341			t.Fatalf("顺序编号计数器不得被改动：before=%d after=%d", before, s.nextResultSeq)
342		}
343		if e := s.Enrollment("s1", "e2"); e == nil || e.Result != Enrolled || e.ResultSeq != 0 {
344			t.Fatalf("未提交的 e2 应保持选课、编号 0，得到 %+v", e)
345		}
346		if w := s.Waiver("s1", "w1"); w == nil || w.Status != WaiverApproved {
347			t.Fatalf("有效免修不得被清除：%+v", w)
348		}
349		if w := s.Waiver("s1", "wbad"); w == nil || w.Status != WaiverRejected {
350			t.Fatalf("被拒绝免修历史不得被清除：%+v", w)
351		}
352		if n := len(s.enrollments); n != 4 {
353			t.Fatalf("不得删除任何修读记录，得到 %d 条", n)
354		}
355	}
356	
357	// TestSaveLegalResultSeqArrangementsAccepted 合法的编号安排继续正常保存，
358	// 学分与来源规则保持不变：
359	//   - 多条尚未提交结果的选课共用编号 0；
360	//   - 已提交编号有空缺（不连续）；
361	//   - 不同学生共用修读编号但顺序编号不同，来源各归本人；
362	//   - 同一要求多次通过只计一份学分，仍按最先提交（编号最小）的通过记录说明来源。
363	func TestSaveLegalResultSeqArrangementsAccepted(t *testing.T) {
364		t.Run("多条选课零编号与跳号成绩并存", func(t *testing.T) {
365			s := saveSeqTwoStudentStore(t)
366			// e1 未通过（1）、e9 通过（5，跳号）；e2 与 s2/e1 仍是选课（0）。
367			if _, _, err := s.SubmitResult("s1", "e1", Failed); err != nil {
368				t.Fatal(err)
369			}
370			if _, _, err := s.SubmitResult("s1", "e9", Passed); err != nil {
371				t.Fatal(err)
372			}
373			s.Enrollment("s1", "e9").ResultSeq = 5 // 2/3/4 空缺，合法。
374			s.nextResultSeq = 5
375	
376			path := filepath.Join(t.TempDir(), "records.json")
377			if err := s.Save(path); err != nil {
378				t.Fatalf("零编号选课并存、已提交编号跳号时应正常保存：%v", err)
379			}
380			loaded, existed, err := Load(path)
381			if err != nil || !existed {
382				t.Fatalf("合法记录保存后应可读取：existed=%v err=%v", existed, err)
383			}
384			// r2 由编号 5 的通过修读满足，3 学分；r1 只有未通过与选课，未满足。
385			rep := loaded.CheckStudent("s1")
386			if rep.TotalCredits != 3 {
387				t.Fatalf("应只凭 e9 的 3 学分课程计 3 学分，得到 %d", rep.TotalCredits)
388			}
389			var r2 *RequirementStatus
390			for i := range rep.Requirements {
391				if rep.Requirements[i].Req.ID == "r2" {
392					r2 = &rep.Requirements[i]
393				}
394			}
395			if r2 == nil || !r2.Satisfied || r2.PassedEnrollmentID != "e9" {
396				t.Fatalf("r2 应由 e9 满足，得到 %+v", r2)
397			}
398			if e := loaded.Enrollment("s1", "e2"); e == nil || e.Result != Enrolled || e.ResultSeq != 0 {
399				t.Fatalf("选课 e2 应保持编号 0，得到 %+v", e)
400			}
401		})
402	
403		t.Run("不同学生同号修读编号不同_正常保存且来源各归本人", func(t *testing.T) {
404			s := saveSeqTwoStudentStore(t)
405			if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
406				t.Fatal(err)
407			}
408			if _, _, err := s.SubmitResult("s2", "e1", Failed); err != nil {
409				t.Fatal(err)
410			}
411			// s1 序号 1（4 学分课程），s2 序号 2（3 学分课程，未通过）。
412	
413			path := filepath.Join(t.TempDir(), "records.json")
414			if err := s.Save(path); err != nil {
415				t.Fatalf("跨学生同号修读、顺序编号不同应正常保存：%v", err)
416			}
417			loaded, _, err := Load(path)
418			if err != nil {
419				t.Fatalf("合法记录保存后应可读取：%v", err)
420			}
421			if rep := loaded.CheckStudent("s1"); rep.TotalCredits != 4 ||
422				rep.Requirements[0].PassedEnrollmentID != "e1" {
423				t.Fatalf("s1 应凭本人 e1 得 4 学分，得到 %+v", rep.Requirements[0])
424			}
425			if rep := loaded.CheckStudent("s2"); rep.TotalCredits != 0 ||
426				len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
427				t.Fatalf("s2 的 e1 未通过，应 0 学分未满足，得到 %+v", rep)
428			}
429			if loaded.Enrollment("s1", "e1") == loaded.Enrollment("s2", "e1") {
430				t.Fatal("两名学生的同号修读应仍是两条独立记录")
431			}
432		})
433	
434		t.Run("同一要求多次通过只计一份_按最小编号说明来源", func(t *testing.T) {
435			s := NewStore()
436			mustStudent(t, s, "s1")
437			mustCourse(t, s, "c1", "高等数学", 4)
438			mustReq(t, s, "s1", "r1", "c1")
439			mustEnroll(t, s, "s1", "r1", "2024春", "e1")
440			mustEnroll(t, s, "s1", "r1", "2024秋", "e2")
441			if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
442				t.Fatal(err)
443			}
444			if _, _, err := s.SubmitResult("s1", "e2", Passed); err != nil {
445				t.Fatal(err)
446			}
447			// 重排为带空缺的编号：e2 编号 2、e1 编号 5，来源仍应是编号较小的 e2。
448			s.Enrollment("s1", "e2").ResultSeq = 2
449			s.Enrollment("s1", "e1").ResultSeq = 5
450			s.nextResultSeq = 9
451	
452			path := filepath.Join(t.TempDir(), "records.json")
453			if err := s.Save(path); err != nil {
454				t.Fatalf("编号各不相同的两次通过应正常保存：%v", err)
455			}
456			loaded, _, err := Load(path)
457			if err != nil {
458				t.Fatalf("合法记录保存后应可读取：%v", err)
459			}
460			rep := loaded.CheckStudent("s1")
461			if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
462				t.Fatalf("同一要求多次通过只计一份 4 学分，得到学分=%d 未满足=%v",
463					rep.TotalCredits, rep.Unmet)
464			}
465			st := rep.Requirements[0]
466			if st.PassedEnrollmentID != "e2" || len(st.PassedEnrollmentIDs) != 2 {
467				t.Fatalf("应以编号较小的通过修读 e2 说明来源且两次通过都保留，得到 %+v", st)
468			}
469		})
470	}
